/** Returns `value` with every object's keys sorted, so equal JSON values serialize identically. */
function canonicalJson(value: unknown): unknown {
	if (Array.isArray(value)) {
		return value.map(canonicalJson);
	}
	if (value !== null && typeof value === 'object') {
		return Object.fromEntries(Object.entries(value).sort(([a], [b]) => (a < b ? -1 : 1)).map(([key, entry]) => [key, canonicalJson(entry)]));
	}
	return value;
}
